 it('tasks enforce dependencies, collaboration and atomic handoff races',async()=>{
  const p=await create(member,'projects',{name:'Delivery'}),a=await create(member,'tasks',{title:'Prerequisite',project_id:p.id}),b=await create(member,'tasks',{title:'Dependent',project_id:p.id});await create(member,'task_dependencies',{task_id:b.id,depends_on_id:a.id});await expect(create(member,'task_dependencies',{task_id:a.id,depends_on_id:b.id})).rejects.toMatchObject({code:'dependency_cycle'});await expect(act(member,'tasks',b,'complete')).rejects.toMatchObject({code:'dependency_incomplete'});await act(member,'tasks',a,'complete');await act(member,'tasks',b,'complete');
  const task=await create(member,'tasks',{title:'Transfer responsibility'});await create(member,'task_collaborators',{task_id:task.id,user_id:recipient.userId,responsibility:'Implementation'});await update(recipient,'tasks',id(task),{version:task.version,notes:'Collaboration persisted'});const h=await create(member,'handoffs',{title:'Handoff',task_id:task.id,to_user_id:recipient.userId,remaining_work:'Check output',next_step:'Review'});expect((await get(member,'tasks',id(task))).owner_id).toBe(member.userId);
  const race=await Promise.allSettled([act(recipient,'handoffs',h,'accept'),act(recipient,'handoffs',h,'accept')]);expect(race.filter(r=>r.status==='fulfilled')).toHaveLength(1);expect((await get(recipient,'tasks',id(task))).owner_id).toBe(recipient.userId);expect((await get(member,'handoffs',id(h))).status).toBe('accepted');await expect(act(recipient,'handoffs',h,'accept')).rejects.toMatchObject({code:'version_conflict'});
 });
