 it('expense partial approval, payment, replay, overpayment, posting, reports, close and reversal',async()=>{
  const debit=await create(fin,'accounts',{code:'6000',name:'Operating expense',kind:'expense',active:true}),credit=await create(fin,'accounts',{code:'1000',name:'Cash',kind:'asset',active:true});const period=await create(fin,'fiscal_periods',{name:'October 2026',start_date:'2026-10-01',end_date:'2026-10-31'});await create(fin,'fiscal_periods',{name:'November 2026',start_date:'2026-11-01',end_date:'2026-11-30'});
  let claim=await create(member,'expense_claims',{title:'Isolated expense',currency:'CAD'});await create(member,'expense_lines',{claim_id:claim.id,description:'Receipt item',expense_date:'2026-10-07',amount_minor:'10001',tax_minor:'500'});claim=await get(member,'expense_claims',id(claim));expect(claim.total_minor).toBe('10501');await expect(get(recipient,'expense_claims',id(claim))).rejects.toMatchObject({status:404});await expect(act(fin,'expense_claims',claim,'pay',{amount_minor:'1',reference:'No approval',idempotency_key:randomUUID()})).rejects.toMatchObject({code:'payment_not_approved'});
  claim=await act(member,'expense_claims',claim,'submit');await query("UPDATE memberships SET roles=ARRAY['member','reviewer'] WHERE workspace_id=$1 AND user_id=$2",[member.workspaceId,member.userId]);try{await expect(act({...member,roles:['member','reviewer']},'expense_claims',claim,'approve',{approved_minor:'8000'})).rejects.toMatchObject({code:'self_approval_forbidden'});}finally{await query("UPDATE memberships SET roles=ARRAY['member'] WHERE workspace_id=$1 AND user_id=$2",[member.workspaceId,member.userId]);}await expect(update(member,'expense_claims',id(claim),{version:claim.version,title:'Unauthorized submitted edit'})).rejects.toMatchObject({code:'record_locked'});claim=await act(reviewer,'expense_claims',claim,'approve',{approved_minor:'8000',reason:'Partial approved'});
  const key=randomUUID(),before=claim;claim=await act(fin,'expense_claims',claim,'pay',{amount_minor:'4000',reference:'TEST-PARTIAL',idempotency_key:key});const replay=await act(fin,'expense_claims',before,'pay',{amount_minor:'4000',reference:'TEST-PARTIAL',idempotency_key:key});expect(replay.payment_id).toBe(claim.payment_id);expect(claim.paid_minor).toBe('4000');await expect(act(fin,'expense_claims',claim,'pay',{amount_minor:'4001',reference:'Overpayment',idempotency_key:randomUUID()})).rejects.toMatchObject({code:'payment_exceeds_balance'});claim=await act(fin,'expense_claims',claim,'pay',{amount_minor:'4000',reference:'TEST-FINAL',idempotency_key:randomUUID()});expect(claim.status).toBe('paid');
  const paymentId=claim.payment_id;claim=await act(fin,'expense_claims',claim,'post',{debit_account_id:debit.id,credit_account_id:credit.id,entry_date:'2026-10-07'});expect(claim.status).toBe('posted');const reports=await analytics(fin,{});expect(reports.finance?.profit_loss.expense_minor).toBe('8000');expect(reports.finance?.trial_balance.reduce((s,r)=>s+BigInt(String(r.debit_minor))-BigInt(String(r.credit_minor)),0n)).toBe(0n);
  let bank=await create(fin,'bank_transactions',{reference:randomUUID(),bank_account:'TEST',transaction_date:'2026-10-07',currency:'CAD',amount_minor:'-4000'});bank=await act(fin,'bank_transactions',bank,'reconcile',{payment_id:paymentId});expect(bank.status).toBe('matched');const bank2=await create(fin,'bank_transactions',{reference:randomUUID(),bank_account:'TEST',transaction_date:'2026-10-07',currency:'CAD',amount_minor:'-4000'});await expect(act(fin,'bank_transactions',bank2,'reconcile',{payment_id:paymentId})).rejects.toMatchObject({code:'already_reconciled'});
  const journal=await get(fin,'journal_entries',String(claim.journal_entry_id));await expect(update(fin,'journal_entries',id(journal),{version:journal.version,title:'Tamper'})).rejects.toMatchObject({code:'posted_journal_immutable'});await act(fin,'fiscal_periods',period,'close');await expect(act(fin,'journal_entries',journal,'reverse',{entry_date:'2026-10-08',reason:'Wrong date'})).rejects.toMatchObject({code:'period_closed_or_missing'});await act(fin,'journal_entries',journal,'reverse',{entry_date:'2026-11-01',reason:'Correct through reversal'});expect((await analytics(fin,{})).finance?.profit_loss.expense_minor).toBe('0');
 });
