  const supplier=await create(ops,'suppliers',{name:'Isolated supplier'});let po=await create(ops,'purchase_orders',{title:'Partial order',supplier_id:supplier.id,currency:'CAD'});const line=await create(ops,'purchase_order_lines',{order_id:po.id,description:'Service units',quantity:'10',unit_price_minor:'1234'});po=await act(ops,'purchase_orders',po,'approve');const key=randomUUID(),before=po;po=await act(ops,'purchase_orders',po,'receive',{line_id:line.id,quantity:'4',idempotency_key:key});await act(ops,'purchase_orders',before,'receive',{line_id:line.id,quantity:'4',idempotency_key:key});expect((await get(ops,'purchase_order_lines',id(line))).received_quantity).toBe('4.000000');await expect(act(ops,'purchase_orders',po,'receive',{line_id:line.id,quantity:'7'})).rejects.toMatchObject({code:'over_receipt'});
