 it('currency configuration rejects invalid digits and preserves used amounts on omitted create or patch',async()=>{
  const [settings]=await fixture();
  for(const minor_digits of [null,'',' ',true,[],{},undefined,1.5,'2.5',-1,7,NaN,Infinity]){
   await expect(create(settings,'currencies',{code:'EUR',name:'Invalid precision',minor_digits})).rejects.toMatchObject({code:'invalid_currency_digits'});
  }
  const created=await create(settings,'currencies',{code:'EUR',name:'Explicit default'});
  expect(created.minor_digits).toBe(2);
  const amount=await create(settings,'subscriptions',{name:'Preserved amount',currency:'EUR',amount_minor:'12345'});
  for(const minor_digits of [null,'',1.5,-1,7]){
   await expect(update(settings,'currencies',id(created),{version:created.version,minor_digits})).rejects.toMatchObject({code:'invalid_currency_digits'});
  }
  await expect(update(settings,'currencies',id(created),{version:created.version,minor_digits:0})).rejects.toMatchObject({code:'currency_in_use'});
  const renamed=await update(settings,'currencies',id(created),{version:created.version,name:'Name-only patch'});
  expect(renamed.minor_digits).toBe(2);
  expect((await query('SELECT minor_digits FROM currencies WHERE workspace_id=$1 AND id=$2',[settings.workspaceId,created.id]))[0].minor_digits).toBe(2);
  expect(await get(settings,'subscriptions',id(amount))).toMatchObject({amount_minor:'12345',currency_minor_digits:2});
  await create(settings,'subscriptions',{name:'Existing standard units',currency:'CAD',amount_minor:'12345'});
  expect((await create(settings,'currencies',{code:'CAD',name:'Late unchanged units'})).minor_digits).toBe(2);
  const yen=await create(settings,'subscriptions',{name:'Existing zero-digit units',currency:'JPY',amount_minor:'12345'});
  await expect(create(settings,'currencies',{code:'JPY',name:'Cannot default over existing zero digits'})).rejects.toMatchObject({code:'currency_in_use'});
  expect((await create(settings,'currencies',{code:'JPY',name:'Explicit zero digits',minor_digits:0})).minor_digits).toBe(0);
  expect(await get(settings,'subscriptions',id(yen))).toMatchObject({amount_minor:'12345',currency_minor_digits:0});
  let custom=await create(settings,'currencies',{code:'CHF',name:'Six-digit boundary',minor_digits:'6'});
  expect(custom.minor_digits).toBe(6);
  custom=await update(settings,'currencies',id(custom),{version:custom.version,name:'Omission retains six digits'});
  expect(custom.minor_digits).toBe(6);
 });
 it('approval policy intervals reject reversed finite bounds on create and partial update',async()=>{
  const [settings,,,approver]=await fixture();
  const base={name:'Bounded approval fixture',reviewer_id:approver.userId};
  await expect(create(settings,'approval_policies',{...base,min_minor:'101',max_minor:'100'})).rejects.toMatchObject({code:'invalid_approval_range'});
  await expect(create(settings,'approval_policies',{...base,min_minor:'9007199254740993',max_minor:'9007199254740992'})).rejects.toMatchObject({code:'invalid_approval_range'});
  const policy=await create(settings,'approval_policies',{...base,min_minor:'100',max_minor:'100'});
  await expect(update(settings,'approval_policies',id(policy),{version:policy.version,min_minor:'101'})).rejects.toMatchObject({code:'invalid_approval_range'});
  await expect(update(settings,'approval_policies',id(policy),{version:policy.version,max_minor:'99'})).rejects.toMatchObject({code:'invalid_approval_range'});
  expect(await get(settings,'approval_policies',id(policy))).toMatchObject({min_minor:'100',max_minor:'100',version:policy.version});
  let unlimited=await update(settings,'approval_policies',id(policy),{version:policy.version,max_minor:'0'});
  unlimited=await update(settings,'approval_policies',id(unlimited),{version:unlimited.version,min_minor:'9007199254740993'});
  expect(unlimited).toMatchObject({min_minor:'9007199254740993',max_minor:'0'});
  expect(await create(settings,'approval_policies',base)).toMatchObject({min_minor:'0',max_minor:'0'});
 });
 it('electronic signatures require reviewed consent and the authenticated name with immutable hash receipts',async()=>{
  const [admin]=await fixture();let contract=await create(admin,'contracts',{title:'Signed internal contract'});contract=await act(admin,'contracts',contract,'review');const data={version:contract.version,signed_document_url:'https://example.invalid/signed-document',idempotency_key:randomUUID()},before=await get(admin,'contracts',id(contract));
  await expect(action(admin,'contracts',id(contract),'sign',data)).rejects.toMatchObject({code:'signature_required'});
  const preview=await previewSignature(admin,'contracts',id(contract),'sign',data);
  await expect(action(admin,'contracts',id(contract),'sign',{...data,signature:{typed_name:'admin operations',consent:false,reviewed_hash:preview.reviewed_hash}})).rejects.toMatchObject({code:'signature_consent_required'});
  await expect(action(admin,'contracts',id(contract),'sign',{...data,signature:{typed_name:'Forged signer',consent:true,reviewed_hash:preview.reviewed_hash,actor_id:member.userId}})).rejects.toMatchObject({code:'signature_name_mismatch'});
  await expect(action(admin,'contracts',id(contract),'sign',{...data,signed_document_url:'https://example.invalid/changed',signature:{typed_name:'admin operations',consent:true,reviewed_hash:preview.reviewed_hash}})).rejects.toMatchObject({code:'signature_snapshot_changed'});
  expect((await get(admin,'contracts',id(contract))).version).toBe(before.version);expect(await listSignatures(admin,'contracts',id(contract))).toHaveLength(0);
  const signed=await action(admin,'contracts',id(contract),'sign',{...data,signature:{typed_name:'admin operations',consent:true,reviewed_hash:preview.reviewed_hash,actor_id:member.userId,actor_roles:['finance'],signed_at:'2000-01-01T00:00:00Z'}});
  const signatures=await listSignatures(admin,'contracts',id(contract));expect(signatures).toHaveLength(1);expect(signatures[0]).toMatchObject({actor_id:admin.userId,actor_name:'admin operations',actor_roles:['admin','operations'],matches_current:true,integrity_valid:true,record_version:contract.version,result_version:signed.version});
  const receipt=await signatureReceipt(admin,String(signatures[0].id));expect(signatureHash(receipt.canonical)).toBe(receipt.sha256);const parsed=JSON.parse(receipt.canonical);expect(parsed.signer.actor_id).toBe(admin.userId);expect(parsed.signed_at).not.toBe('2000-01-01T00:00:00Z');expect(parsed.reviewed.values).not.toHaveProperty('idempotency_key');expect(parsed.reviewed.values).not.toHaveProperty('signature');
  expect(await action(admin,'contracts',id(contract),'sign',data)).toEqual(JSON.parse(JSON.stringify(signed)));expect(await listSignatures(admin,'contracts',id(contract))).toHaveLength(1);
  await expect(query('UPDATE electronic_signatures SET typed_name=$1 WHERE id=$2',['Tampered',signatures[0].id])).rejects.toMatchObject({code:'23514'});
  await expect(query('DELETE FROM electronic_signatures WHERE id=$1',[signatures[0].id])).rejects.toMatchObject({code:'23514'});
  await update(admin,'contracts',id(signed),{version:signed.version,obligations:'New content after confirmation'});expect((await listSignatures(admin,'contracts',id(contract)))[0].matches_current).toBe(false);expect(await signatureReceipt(admin,String(signatures[0].id))).toEqual(receipt);
 });
