 it('signature preview and child edits use parent-before-child locks without a deadlock',async()=>{
  const [,author,,approver]=await fixture();let task=await create(author,'tasks',{title:'Concurrent signed review'});const child=await create(author,'task_checklist',{task_id:task.id,title:'Concurrent checklist item'});task=await act(author,'tasks',task,'submit_review',{reviewer_id:approver.userId,deliverable:'Complete review snapshot'});const review=(await list(approver,'reviews',{task_id:task.id})).rows[0],holder=await pool.connect();let edits:Promise<PromiseSettledResult<Row>[]>|undefined;
  try{await holder.query('BEGIN');await holder.query("SET LOCAL lock_timeout='1500ms'");const pid=(await holder.query('SELECT pg_backend_pid() AS pid')).rows[0].pid;await holder.query('SELECT id FROM tasks WHERE id=$1 FOR UPDATE',[task.id]);
   edits=Promise.allSettled([update(author,'task_checklist',id(child),{version:child.version,completed:true})]);
   // Wait for observed PostgreSQL blocking, allowing permission-graph planning on a busy host.
   let waiting=false;const deadline=Date.now()+10000;while(Date.now()<deadline){if((await query('SELECT 1 FROM pg_stat_activity WHERE datname=current_database() AND $1=ANY(pg_blocking_pids(pid))',[pid])).length){waiting=true;break;}await new Promise(resolve=>setTimeout(resolve,25));}expect(waiting).toBe(true);
   // An updater blocked on its parent must not already hold the child lock.
   await holder.query('SELECT id FROM task_checklist WHERE id=$1 FOR UPDATE',[child.id]);const preview=previewSignature(approver,'reviews',id(review),'approve',{version:review.version,reason:'Concurrent review'});await holder.query('COMMIT');expect((await edits)[0].status).toBe('fulfilled');expect((await preview).required).toBe(true);expect((await get(author,'task_checklist',id(child))).completed).toBe(true);
  }finally{await holder.query('ROLLBACK');holder.release();if(edits)await edits;}
 });
